def sub_array_ranges(nums):
    def contribution(target):
        # True -> sum as maximum; False -> sum as minimum
        n = len(nums)
        prev = [-1] * n
        nxt = [n] * n
        stack = []
        for i in range(n):
            while stack and (
                (nums[stack[-1]] < nums[i]) if target else (nums[stack[-1]] > nums[i])
            ):
                stack.pop()
            prev[i] = stack[-1] if stack else -1
            stack.append(i)
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and (
                (nums[stack[-1]] <= nums[i]) if target else (nums[stack[-1]] >= nums[i])
            ):
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)
        return sum((i - prev[i]) * (nxt[i] - i) * nums[i] for i in range(n))

    return contribution(True) - contribution(False)

