#include <bits/stdc++.h>
using namespace std;

long long subArrayRanges(vector<int>& arr) {
    auto bounds = [&](bool asMax) {
        int n = arr.size();
        vector<int> prev(n, -1), nxt(n, n);
        stack<int> st;
        for (int i = 0; i < n; ++i) {
            while (!st.empty() && (asMax ? arr[st.top()] < arr[i] : arr[st.top()] > arr[i])) st.pop();
            if (!st.empty()) prev[i] = st.top();
            st.push(i);
        }
        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; --i) {
            while (!st.empty() && (asMax ? arr[st.top()] <= arr[i] : arr[st.top()] >= arr[i])) st.pop();
            if (!st.empty()) nxt[i] = st.top();
            st.push(i);
        }
        long long sum = 0;
        for (int i = 0; i < n; ++i)
            sum += (long long)(i - prev[i]) * (nxt[i] - i) * arr[i];
        return sum;
    };
    return bounds(true) - bounds(false);
}

