import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public long subArrayRanges(int[] nums) {
        return contribution(nums, true) - contribution(nums, false);
    }

    private long contribution(int[] a, boolean asMax) {
        int n = a.length;
        int[] prev = new int[n], nxt = new int[n];
        java.util.Arrays.fill(prev, -1);
        java.util.Arrays.fill(nxt, n);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; ++i) {
            while (!stack.isEmpty() &&
                   (asMax ? a[stack.peek()] < a[i] : a[stack.peek()] > a[i])) stack.pop();
            if (!stack.isEmpty()) prev[i] = stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!stack.isEmpty() &&
                   (asMax ? a[stack.peek()] <= a[i] : a[stack.peek()] >= a[i])) stack.pop();
            if (!stack.isEmpty()) nxt[i] = stack.peek();
            stack.push(i);
        }
        long sum = 0;
        for (int i = 0; i < n; ++i)
            sum += (long)(i - prev[i]) * (nxt[i] - i) * a[i];
        return sum;
    }
}
